package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"
)

type Format int

const (
	FormatYAML Format = iota
	FormatTOML
	FormatJSON
	FormatHCL
)

func (f Format) Name() string {
	switch f {
	case FormatYAML:
		return "YAML"
	case FormatTOML:
		return "TOML"
	case FormatJSON:
		return "JSON"
	case FormatHCL:
		return "HCL"
	}
	return ""
}

type Pair struct {
	Key   string
	Value interface{}
}

type OrderedMap struct {
	Pairs []Pair
}

func (m *OrderedMap) Get(key string) (interface{}, bool) {
	for _, p := range m.Pairs {
		if p.Key == key {
			return p.Value, true
		}
	}
	return nil, false
}

func (m *OrderedMap) Set(key string, v interface{}) {
	for i, p := range m.Pairs {
		if p.Key == key {
			m.Pairs[i].Value = v
			return
		}
	}
	m.Pairs = append(m.Pairs, Pair{key, v})
}

// EmptyDocument is a marker for a YAML input with no document (empty input,
// whitespace or comments only). It converts to empty output.
type emptyDocument struct{}

type options struct {
	noConvert  bool
	escapeHTML bool
	indent     bool
	parseKeys  bool
	source     Format
	target     Format
}

// normalizeNumber converts ints coming from libraries to int64 when possible.
func normalizeNumber(v interface{}) interface{} {
	switch n := v.(type) {
	case int:
		return int64(n)
	case int8:
		return int64(n)
	case int16:
		return int64(n)
	case int32:
		return int64(n)
	case uint8:
		return int64(n)
	case uint16:
		return int64(n)
	case uint32:
		return int64(n)
	}
	return v
}

// jsonFloatText formats a finite float the way encoding/json does.
// json.Marshal is used for that.
func jsonFloatText(f float64) string {
	b := marshalJSONFloat(f)
	return b
}

func formatFloatJSON(f float64) string {
	return jsonFloatText(f)
}

// stringifyKey converts a non-string map key (from YAML documents) to the
// string form used for every output format, following observed behaviour.
func stringifyKey(v interface{}, opts *options) string {
	switch t := v.(type) {
	case nil:
		return "null"
	case string:
		return t
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case int:
		return strconv.Itoa(t)
	case float64:
		if math.IsInf(t, 1) {
			if opts != nil && opts.noConvert {
				return formatFloatJSON(math.MaxFloat64)
			}
			return "Infinity"
		}
		if math.IsInf(t, -1) {
			if opts != nil && opts.noConvert {
				return formatFloatJSON(-math.MaxFloat64)
			}
			return "-Infinity"
		}
		if math.IsNaN(t) {
			if opts != nil && opts.noConvert {
				return "null"
			}
			return "NaN"
		}
		return formatFloatJSON(t)
	case time.Time:
		return t.String()
	case []interface{}, *OrderedMap:
		// Composite keys are represented by their compact JSON form.
		if opts == nil {
			opts = &options{}
		}
		b, err := encodeJSONValue(t, opts)
		if err == nil {
			// encodeJSONValue adds no trailing newline in this helper form
			return strings.TrimSuffix(string(b), "\n")
		}
		return fmt.Sprintf("%v", t)
	default:
		return fmt.Sprintf("%v", t)
	}
}

// convertTimeForJSON converts TOML local date/time values (which carry a
// synthetic location from the TOML library) to the same wall-clock in UTC.
// Other times keep their location.
func normalizeTime(t time.Time) time.Time {
	loc := t.Location()
	if loc == nil {
		return t
	}
	switch loc.String() {
	case "time-local", "date-local", "datetime-local", "localtime", "localdate", "localdatetime":
		return time.Date(t.Year(), t.Month(), t.Day(), t.Hour(), t.Minute(), t.Second(), t.Nanosecond(), time.UTC)
	}
	return t
}

func formatTimeRFC3339(t time.Time) string {
	t = normalizeTime(t)
	return t.Format("2006-01-02T15:04:05.999999999Z07:00")
}

// transformInfStrings converts strings "Infinity", "-Infinity" and "NaN" to
// the corresponding floats. Used for JSON/HCL sources when writing YAML/TOML.
func transformInfStrings(v interface{}) interface{} {
	switch t := v.(type) {
	case string:
		switch t {
		case "Infinity":
			return math.Inf(1)
		case "-Infinity":
			return math.Inf(-1)
		case "NaN":
			return math.NaN()
		}
		return t
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, e := range t {
			out[i] = transformInfStrings(e)
		}
		return out
	case *OrderedMap:
		out := &OrderedMap{}
		for _, p := range t.Pairs {
			out.Pairs = append(out.Pairs, Pair{p.Key, transformInfStrings(p.Value)})
		}
		return out
	default:
		return v
	}
}
