package main

import (
	"bytes"
	"encoding/json"
	"math"
	"strconv"
	"strings"
	"time"
)

func marshalJSONFloat(f float64) string {
	b, _ := json.Marshal(f)
	return string(b)
}

// jsonString encodes a string using encoding/json with configurable HTML escaping.
func jsonString(s string, escapeHTML bool) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(escapeHTML)
	_ = enc.Encode(s)
	return strings.TrimSuffix(buf.String(), "\n")
}

// encodeJSONValue encodes the internal value as JSON. Returns bytes without
// a trailing newline when used via encodeJSONHelper; the public encodeJSON adds it.
func encodeJSONValue(v interface{}, opts *options) ([]byte, error) {
	var buf bytes.Buffer
	w := &jsonWriter{buf: &buf, opts: opts}
	if err := w.write(v, 0); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func encodeJSON(v interface{}, opts *options) ([]byte, error) {
	b, err := encodeJSONValue(v, opts)
	if err != nil {
