{"command":"cat > yaml.go <<'EOF'
package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

func parseYAML(data []byte, opts *options) (interface{}, error) {
	return parseYAMLDocument(data, opts)
}

func parseYAMLDocument(data []byte, opts *options) (interface{}, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var node yaml.Node
	err := dec.Decode(&node)
	if err != nil {
		if errors.Is(err, io.EOF) {
			return emptyDocument{}, nil
		}
		return nil, err
	}
	if len(node.Content) == 0 {
		return emptyDocument{}, nil
	}
	conv := &nodeConverter{opts: opts, active: make(map[*yaml.Node]bool)}
	v, err := conv.convert(node.Content[0])
	if err != nil {
		return nil, err
	}
	if v == nil {
		// A document consisting of e.g. "---" decodes to nil; distinguish
		// that from the no-document case above. Keep nil.
		return nil, nil
	}
	return v, nil
}

type nodeConverter struct {
	opts   *options
	active map[*yaml.Node]bool
}

func (c *nodeConverter) convert(n *yaml.Node) (interface{}, error) {
	if n == nil {
		return nil, nil
	}
	if c.active[n] {
		return nil, fmt.Errorf("anchor '%s' value contains itself", n.Anchor)
	}
	c.active[n] = true
	defer delete(c.active, n)

	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return emptyDocument{}, nil
		}
		return c.convert(n.Content[0])
	case yaml.AliasNode:
		if n.Alias != nil && c.active[n.Alias] {
			return nil, fmt.Errorf("anchor '%s' value contains itself", n.Alias.Anchor)
		}
		return c.convert(n.Alias)
	case yaml.MappingNode:
		m := &OrderedMap{}
		for i := 0; i+1 < len(n.Content); i += 2 {
			kn := n.Content[i]
			vn := n.Content[i+1]
			if kn.Tag == "!!merge" {
				mv, err := c.convert(vn)
				if err != nil {
					return nil, err
				}
				mm, ok := mv.(*OrderedMap)
				if !ok {
					return nil, fmt.Errorf("map merge requires map or sequence of maps as the value")
				}
				m.Pairs = append(m.Pairs, mm.Pairs...)
				continue
			}
			kv, err := c.convert(kn)
			if err != nil {
				return nil, err
			}
			key := stringifyKey(kv, c.opts)
			vv, err := c.convert(vn)
			if err != nil {
				return nil, err
			}
			m.Pairs = append(m.Pairs, Pair{key, vv})
		}
		return m, nil
	case yaml.SequenceNode:
		out := make([]interface{}, 0, len(n.Content))
		for _, child := range n.Content {
			v, err := c.convert(child)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case yaml.ScalarNode:
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return nil, fmt.Errorf("scalar decode error: %w", err)
		}
		return normalizeNumber(v), nil
	}
	return nil, nil
}

// formatYAMLFloat formats a float in the style of the YAML emitter used by
// the original program (Go yaml v2 style).
func formatYAMLFloat(f float64) string {
	if math.IsInf(f, 1) {
		return ".inf"
	}
	if math.IsInf(f, -1) {
		return "-.inf"
	}
	if math.IsNaN(f) {
		return ".nan"
	}
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.ContainsAny(s, ".eE") && !strings.HasPrefix(s, "-") {
		s += ".0"
	}
	return s
}

func scalarNode(v interface{}, opts *options) (*yaml.Node, error) {
	var node yaml.Node
	switch t := v.(type) {
	case nil:
		node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: "null"}
		return &node, nil
	case bool:
		if t {
			node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: "true"}
		} else {
			node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: "false"}
		}
		return &node, nil
	case string:
		if err := node.Encode(t); err != nil {
			return nil, err
		}
		return &node, nil
	case int64:
		node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: strconv.FormatInt(t, 10)}
		return &node, nil
	case uint64:
		node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: strconv.FormatUint(t, 10)}
		return &node, nil
	case int:
		node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: strconv.Itoa(t)}
		return &node, nil
	case float64:
		node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: formatYAMLFloat(t)}
		return &node, nil
	case time.Time:
		node = yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: formatTimeRFC3339(t)}
		return &node, nil
	default:
		if err := node.Encode(t); err != nil {
			return nil, err
		}
		return &node, nil
	}
}

func valueToYAMLNode(v interface{}, opts *options) (*yaml.Node, error) {
	switch t := v.(type) {
	case *OrderedMap:
		node := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		if t == nil {
			return node, nil
		}
		for _, p := range t.Pairs {
			kn, err := keyToYAMLNode(p.Key, opts)
			if err != nil {
				return nil, err
			}
			vn, err := valueToYAMLNode(p.Value, opts)
			if err != nil {
				return nil, err
			}
			node.Content = append(node.Content, kn, vn)
		}
		return node, nil
	case []interface{}:
		node := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, e := range t {
			cn, err := valueToYAMLNode(e, opts)
			if err != nil {
				return nil, err
			}
			node.Content = append(node.Content, cn)
		}
		return node, nil
	default:
		return scalarNode(v, opts)
	}
}

func keyToYAMLNode(key string, opts *options) (*yaml.Node, error) {
	if opts.parseKeys {
		if parsed, ok, err := parseKeyAsValue(key, opts); err != nil {
			return nil, err
		} else if ok {
			if parsed == nil {
				return nil, fmt.Errorf("reflect: call of reflect.Value.Set on zero Value")
			}
			return valueToYAMLNode(parsed, opts)
		}
	}
	if !opts.noConvert {
		switch key {
		case "Infinity":
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: ".inf"}, nil
		case "-Infinity":
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: "-.inf"}, nil
		case "NaN":
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "", Value: ".nan"}, nil
		}
	}
	var node yaml.Node
	if err := node.Encode(key); err != nil {
		return nil, err
	}
	return &node, nil
}

// parseKeyAsValue attempts to parse a map key string as a JSON value
// (objects, arrays, numbers, booleans, null). Returns ok=false if it is not
// such a value.
func parseKeyAsValue(s string, opts *options) (interface{}, bool, error) {
	if s == "" {
		return nil, false, nil
	}
	// Objects and arrays: reuse the JSON parser to preserve order.
	trimmed := strings.TrimSpace(s)
