}

// childOrder returns keys of m in order of first appearance under path.
func (c *tomlBuildCtx) childOrder(path []string, m map[string]interface{}) []string {
	var order []string
	seen := map[string]bool{}
	for _, k := range c.keys {
		if len(k) > len(path) && keyHasPrefix(k, path) {
			child := k[len(path)]
			if _, ok := m[child]; ok && !seen[child] {
				seen[child] = true
				order = append(order, child)
			}
		}
	}
	// Any keys not covered (shouldn't happen) are appended in the order
	// they occur in the map iteration fallback: keep them at the end.
	for k := range m {
		if !seen[k] {
			// Insert deterministically later; temporary collect
			order = append(order, k)
			seen[k] = true
		}
	}
	return order
}

