	switch t := v.(type) {
	case map[string]interface{}:
		m := &OrderedMap{}
		for _, k := range c.childOrder(path, t) {
			childPath := append(append([]string{}, path...), k)
			m.Pairs = append(m.Pairs, Pair{k, c.buildValue(t[k], childPath)})
		}
