		}
	}
	return val.Interface()
}

func encodeTOML(v interface{}, opts *options) ([]byte, error) {
	if opts.source == FormatJSON || opts.source == FormatHCL {
		if !opts.noConvert {
			v = transformInfStrings(v)
		}
	}
	converted := toTOMLValue(v, opts)
	var buf bytes.Buffer
	enc := toml.NewEncoder(&buf)
	if opts.indent {
		enc.Indent = "  "
	} else {
		enc.Indent = ""
	}
	if err := enc.Encode(converted); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
