package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type hclTokType int

const (
	hTokEOF hclTokType = iota
	hTokIdent
	hTokString
	hTokNumber
	hTokFloat
	hTokBool
	hTokLBrace
	hTokRBrace
	hTokLBrack
	hTokRBrack
	hTokAssign
	hTokComma
	hTokPeriod
	hTokAdd
	hTokSub
)

func (t hclTokType) Name() string {
	switch t {
	case hTokEOF:
		return "EOF"
	case hTokIdent:
		return "IDENT"
	case hTokString:
		return "STRING"
	case hTokNumber:
		return "NUMBER"
	case hTokFloat:
		return "FLOAT"
	case hTokBool:
		return "BOOL"
	case hTokLBrace:
		return "LBRACE"
	case hTokRBrace:
		return "RBRACE"
	case hTokLBrack:
		return "LBRACK"
	case hTokRBrack:
		return "RBRACK"
	case hTokAssign:
		return "ASSIGN"
	case hTokComma:
		return "COMMA"
	case hTokPeriod:
		return "PERIOD"
	case hTokAdd:
		return "ADD"
	case hTokSub:
		return "SUB"
	}
	return "EOF"
}

type hclToken struct {
	typ  hclTokType
	text string // decoded value for strings, raw text for others
	line int
	col  int
}

type hclLexer struct {
	input string
	pos   int // byte offset of next char
	line  int
	col   int
}

func newHCLLexer(s string) *hclLexer {
	return &hclLexer{input: s, line: 1, col: 1}
}

func (l *hclLexer) errorf(line, col int, format string, args ...interface{}) error {
	return fmt.Errorf("At %d:%d: %s", line, col, fmt.Sprintf(format, args...))
}

// peekRune returns rune at pos and its size, without consuming.
func (l *hclLexer) peekRune() (rune, int) {
	if l.pos >= len(l.input) {
		return utf8.RuneError, 0
	}
	r, sz := utf8.DecodeRuneInString(l.input[l.pos:])
	return r, sz
}

func (l *hclLexer) peekRuneAt(off int) (rune, int) {
	if l.pos+off >= len(l.input) {
		return utf8.RuneError, 0
	}
	r, sz := utf8.DecodeRuneInString(l.input[l.pos+off:])
	return r, sz
}

// nextRune consumes a rune and advances line/col. Returns (r, size).
func (l *hclLexer) nextRune() rune {
	if l.pos >= len(l.input) {
		return utf8.RuneError
	}
	r, sz := utf8.DecodeRuneInString(l.input[l.pos:])
	l.pos += sz
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}

func (l *hclLexer) nextToken() (hclToken, error) {
	// Skip whitespace and comments.
	for {
		if l.pos >= len(l.input) {
			return hclToken{typ: hTokEOF, line: l.line, col: l.col}, nil
		}
		r, sz := l.peekRune()
		if r == utf8.RuneError && sz == 1 {
			return hclToken{}, l.errorf(l.line, l.col, "illegal UTF-8 encoding")
		}
		if r == ' ' || r == '\t' || r == '\r' || r == '\n' {
			l.nextRune()
			continue
		}
		if r == '#' {
			for l.pos < len(l.input) {
				c := l.nextRune()
				if c == '\n' {
					break
				}
			}
			continue
		}
		if r == '/' {
			if r2, _ := l.peekRuneAt(sz); r2 == '/' {
				for l.pos < len(l.input) {
					c := l.nextRune()
					if c == '\n' {
						break
					}
				}
				continue
			} else if r2 == '*' {
				startLine, startCol := l.line, l.col
				l.nextRune()
				l.nextRune()
				closed := false
				for l.pos < len(l.input) {
					c := l.nextRune()
					if c == '*' {
						if r3, _ := l.peekRune(); r3 == '/' {
							l.nextRune()
							closed = true
							break
						}
					}
				}
				if !closed {
					return hclToken{}, l.errorf(l.line, l.col, "comment not terminated")
				}
				_ = startLine
				_ = startCol
				continue
			}
			return hclToken{}, l.errorf(l.line, l.col, "illegal char")
		}
		break
	}

	line, col := l.line, l.col
	r, _ := l.peekRune()

	switch {
	case r == '{':
		l.nextRune()
		return hclToken{hTokLBrace, "{", line, col}, nil
	case r == '}':
		l.nextRune()
		return hclToken{hTokRBrace, "}", line, col}, nil
	case r == '[':
		l.nextRune()
		return hclToken{hTokLBrack, "[", line, col}, nil
	case r == ']':
		l.nextRune()
		return hclToken{hTokRBrack, "]", line, col}, nil
	case r == '=':
		l.nextRune()
		return hclToken{hTokAssign, "=", line, col}, nil
	case r == ',':
		l.nextRune()
		return hclToken{hTokComma, ",", line, col}, nil
	case r == '+':
		l.nextRune()
		return hclToken{hTokAdd, "+", line, col}, nil
	case r == '-':
		l.nextRune()
		return hclToken{hTokSub, "-", line, col}, nil
	case r == '.':
		// Number starting with '.' followed by digit, or PERIOD.
		if r2, _ := l.peekRuneAt(1); r2 >= '0' && r2 <= '9' {
			return l.scanNumber()
		}
		l.nextRune()
		return hclToken{hTokPeriod, ".", line, col}, nil
	case r == '"':
		return l.scanString()
	case r == '<':
		// Heredoc or illegal.
		if r2, _ := l.peekRuneAt(1); r2 == '<' {
			return l.scanHeredoc()
		}
		return hclToken{}, l.errorf(line, col, "illegal char")
	case r >= '0' && r <= '9':
		return l.scanNumber()
	case r == '_' || unicode.IsLetter(r):
		// Identifier: letters, digits, '_', '-', '.'
		start := l.pos
		for l.pos < len(l.input) {
			c, sz := l.peekRune()
			if c == utf8.RuneError && sz == 1 {
				return hclToken{}, l.errorf(l.line, l.col, "illegal UTF-8 encoding")
			}
			if unicode.IsLetter(c) || unicode.IsDigit(c) || c == '_' || c == '-' || c == '.' {
				l.nextRune()
			} else {
				break
			}
		}
		text := l.input[start:l.pos]
		if text == "true" || text == "false" {
			return hclToken{hTokBool, text, line, col}, nil
		}
		return hclToken{hTokIdent, text, line, col}, nil
	}
	return hclToken{}, l.errorf(line, col, "illegal char")
}

func (l *hclLexer) scanNumber() (hclToken, error) {
	line, col := l.line, l.col
	start := l.pos
	// Hex
	if l.pos < len(l.input) && l.input[l.pos] == '0' {
		if r2, _ := l.peekRuneAt(1); r2 == 'x' || r2 == 'X' {
			l.nextRune()
			l.nextRune()
			hexStart := l.pos
			for l.pos < len(l.input) {
				c, _ := l.peekRune()
				if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') {
					l.nextRune()
				} else {
					break
				}
			}
			if l.pos == hexStart {
				return hclToken{}, l.errorf(l.line, l.col, "illegal hexadecimal number")
			}
			return hclToken{hTokNumber, l.input[start:l.pos], line, col}, nil
		}
	}
	isFloat := false
	leadingDot := false
	if r, _ := l.peekRune(); r == '.' {
		leadingDot = true
		isFloat = true
		l.nextRune()
	}
	for l.pos < len(l.input) {
		c, _ := l.peekRune()
		if c >= '0' && c <= '9' {
			l.nextRune()
		} else {
			break
		}
	}
	if !leadingDot {
		if c, _ := l.peekRune(); c == '.' {
			isFloat = true
			l.nextRune()
			for l.pos < len(l.input) {
				c2, _ := l.peekRune()
				if c2 >= '0' && c2 <= '9' {
					l.nextRune()
				} else {
					break
				}
			}
		}
	}
	// Exponent, but not after a leading-dot number such as .5 (matches quirks).
	if !leadingDot {
		if c, _ := l.peekRune(); c == 'e' || c == 'E' {
			isFloat = true
			l.nextRune()
			if c2, _ := l.peekRune(); c2 == '+' || c2 == '-' {
				l.nextRune()
			}
			for l.pos < len(l.input) {
				c2, _ := l.peekRune()
				if c2 >= '0' && c2 <= '9' {
					l.nextRune()
				} else {
					break
				}
			}
		}
	}
	typ := hTokNumber
	if isFloat && !leadingDot {
		typ = hTokFloat
	}
	if leadingDot {
		typ = hTokNumber
	}
	return hclToken{typ, l.input[start:l.pos], line, col}, nil
}

func (l *hclLexer) scanString() (hclToken, error) {
	line, col := l.line, l.col
	l.nextRune() // opening quote
	var sb strings.Builder
	sawNewline := false
	unterminated := false
	for {
		if l.pos >= len(l.input) {
			return hclToken{}, l.errorf(l.line, l.col, "literal not terminated")
		}
		// Invalid UTF-8
		{
			_, sz := l.peekRune()
			// Detect invalid encoding: DecodeRune returns RuneError size 1 for invalid
			if sz == 1 {
				if r, _ := utf8.DecodeRuneInString(l.input[l.pos:]); r == utf8.RuneError {
					// Need distinguish a genuine U+FFFD (size 3) from invalid byte.
					if l.input[l.pos] >= 0x80 {
						return hclToken{}, l.errorf(l.line, l.col, "illegal UTF-8 encoding")
					}
				}
			}
		}
		c := l.nextRune()
		if c == '"' {
			if sawNewline || unterminated {
				return hclToken{}, l.errorf(l.line, l.col, "literal not terminated")
			}
			return hclToken{hTokString, sb.String(), line, col}, nil
		}
		if c == '\n' {
			sawNewline = true
			sb.WriteRune(c)
			continue
		}
		if c == '\\' {
			if l.pos >= len(l.input) {
				return hclToken{}, l.errorf(l.line, l.col, "literal not terminated")
			}
			escLine, escCol := l.line, l.col
			e := l.nextRune()
			switch e {
			case 'n':
				sb.WriteRune('\n')
			case 'r':
				sb.WriteRune('\r')
			case 't':
				sb.WriteRune('\t')
			case 'b':
				sb.WriteRune('\b')
			case 'f':
				sb.WriteRune('\f')
			case 'v':
				sb.WriteRune('\v')
			case '"':
				sb.WriteRune('"')
			case '\\':
				sb.WriteRune('\\')
			case '/':
				return hclToken{}, l.errorf(escLine, escCol, "illegal char escape")
			case 'u', 'U':
				n := 4
				if e == 'U' {
					n = 8
				}
				val := 0
				bad := false
				for i := 0; i < n; i++ {
					if l.pos >= len(l.input) {
						return hclToken{}, l.errorf(l.line, l.col, "literal not terminated")
					}
					h := l.nextRune()
					d, ok := hexVal(h)
					if !ok {
						bad = true
						break
					}
					val = val*16 + d
				}
				if bad {
					unterminated = true
					continue
				}
				sb.WriteRune(rune(val))
			default:
				// Unknown escape: mark unterminated and continue scanning,
				// mirroring observed behaviour for \x.
				unterminated = true
			}
			continue
		}
		sb.WriteRune(c)
	}
}

func hexVal(r rune) (int, bool) {
	switch {
	case r >= '0' && r <= '9':
		return int(r - '0'), true
	case r >= 'a' && r <= 'f':
		return int(r-'a') + 10, true
	case r >= 'A' && r <= 'F':
		return int(r-'A') + 10, true
	}
	return 0, false
}

func (l *hclLexer) scanHeredoc() (hclToken, error) {
	line, col := l.line, l.col
	l.nextRune() // <
	l.nextRune() // <
	indented := false
	if c, _ := l.peekRune(); c == '-' {
		indented = true
		l.nextRune()
	}
	// Marker: identifier characters until newline.
	markerStart := l.pos
	for l.pos < len(l.input) {
		c, _ := l.peekRune()
		if unicode.IsLetter(c) || unicode.IsDigit(c) || c == '_' {
			l.nextRune()
		} else {
			break
		}
	}
	marker := l.input[markerStart:l.pos]
	if marker == "" {
		return hclToken{}, l.errorf(l.line, l.col, "invalid characters in heredoc anchor")
	}
	// Expect newline; any other char is invalid anchor characters.
	if c, _ := l.peekRune(); c != '\n' {
		if l.pos >= len(l.input) {
			return hclToken{}, l.errorf(l.line, l.col, "heredoc not terminated")
		}
		return hclToken{}, l.errorf(l.line, l.col, "invalid characters in heredoc anchor")
	}
	l.nextRune() // newline

	var content strings.Builder
	for {
		if l.pos >= len(l.input) {
			return hclToken{}, l.errorf(l.line, l.col, "heredoc not terminated")
		}
		// Read one line.
		lineStartPos := l.pos
		lineStartLine := l.line
		// consume until newline or EOF
		foundNL := false
		for l.pos < len(l.input) {
			c := l.nextRune()
			if c == '\n' {
				foundNL = true
				break
			}
		}
		textLine := l.input[lineStartPos:l.pos]
		if foundNL {
			textLine = strings.TrimSuffix(textLine, "\n")
		}
		trimmedLeft := strings.TrimLeft(textLine, " \t")
		isTerminator := false
		if trimmedLeft == marker && foundNL {
			if !indented {
				isTerminator = true
			} else {
				// Indented heredoc terminator requires indentation.
				if len(trimmedLeft) != len(textLine) {
					isTerminator = true
				}
			}
		}
		if isTerminator {
			indentStr := textLine[:len(textLine)-len(trimmedLeft)]
			body := content.String()
			if indented && indentStr != "" {
				// Strip a tab indentation as observed.
				if strings.Trim(indentStr, "\t") == "" {
					lines := strings.SplitAfter(body, "\n")
					for i, ln := range lines {
						lines[i] = strings.TrimPrefix(ln, indentStr)
					}
					body = strings.Join(lines, "")
				}
			} else if !indented && indentStr != "" {
				// Non-indented heredoc with an indented terminator keeps
				// the terminator indentation in the value.
				body += indentStr
			}
			return hclToken{hTokString, body, line, col}, nil
		}
		if !foundNL {
			// Terminator line without trailing newline does not count.
			if trimmedLeft == marker {
				return hclToken{}, l.errorf(lineStartLine, len(textLine)+1, "heredoc not terminated")
			}
			return hclToken{}, l.errorf(l.line, l.col, "heredoc not terminated")
		}
		content.WriteString(textLine)
		content.WriteString("\n")
	}
}

// Parser

type hclObject struct {
	items []*hclItem
}

type hclItem struct {
	keys     []string
	value    interface{} // scalar, []interface{}, *hclObject, hclNoValue
	hasValue bool
}

type hclNoValue struct{}

type hclParser struct {
	lex       *hclLexer
	peeked    *hclToken
	peekError error
	hasPeek   bool
}

func (p *hclParser) peek() (hclToken, error) {
	if p.hasPeek {
		return *p.peeked, p.peekError
	}
	tok, err := p.lex.nextToken()
	p.peeked = &tok
	p.peekError = err
	p.hasPeek = true
	return tok, err
}

func (p *hclParser) next() (hclToken, error) {
	if p.hasPeek {
		tok := *p.peeked
		err := p.peekError
		p.hasPeek = false
		p.peeked = nil
		p.peekError = nil
		return tok, err
	}
	return p.lex.nextToken()
}

func atErr(tok hclToken, format string, args ...interface{}) error {
	return fmt.Errorf("At %d:%d: %s", tok.line, tok.col, fmt.Sprintf(format, args...))
}

func (p *hclParser) parseTop() (*hclObject, error) {
	obj, err := p.parseObjectList(false)
	if err != nil {
		return nil, err
	}
	return obj, nil
}

func (p *hclParser) parseObjectList(inBlock bool) (*hclObject, error) {
	obj := &hclObject{}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.typ == hTokEOF {
			if inBlock {
				return nil, atErr(tok, "object expected closing RBRACE got: EOF")
			}
			return obj, nil
		}
		if tok.typ == hTokRBrace {
			if inBlock {
				_, _ = p.next()
				return obj, nil
			}
			return nil, atErr(tok, "expected: IDENT | STRING | ASSIGN | LBRACE got: RBRACE")
		}
		if tok.typ == hTokComma {
			_, _ = p.next()
			continue
		}
		item, err := p.parseObjectItem()
		if err != nil {
			return nil, err
		}
		if item != nil {
			obj.items = append(obj.items, item)
		}
	}
}

func (p *hclParser) parseObjectItem() (*hclItem, error) {
	tok, err := p.peek()
	if err != nil {
		return nil, err
	}
	if tok.typ != hTokIdent && tok.typ != hTokString {
		return nil, atErr(tok, "expected: IDENT | STRING | ASSIGN | LBRACE got: %s", tok.typ.Name())
	}
	var keys []string
	for {
		t, err := p.peek()
		if err != nil {
			return nil, err
		}
		if t.typ == hTokIdent || t.typ == hTokString {
			_, _ = p.next()
			keys = append(keys, t.text)
		} else {
			break
		}
	}
	nt, err := p.peek()
	if err != nil {
		return nil, err
	}
	if nt.typ == hTokAssign {
		if len(keys) > 1 {
			return nil, atErr(nt, "nested object expected: LBRACE got: ASSIGN")
		}
		_, _ = p.next()
		v, has, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		return &hclItem{keys: keys, value: v, hasValue: has}, nil
	}
	if nt.typ == hTokLBrace {
		_, _ = p.next()
		body, err := p.parseObjectList(true)
		if err != nil {
			return nil, err
		}
		return &hclItem{keys: keys, value: body, hasValue: true}, nil
	}
	return nil, atErr(nt, "key '%s' expected start of object ('{') or assignment ('=')", keys[len(keys)-1])
}

// parseValue parses a value after '='. Returns hasValue=false for EOF.
func (p *hclParser) parseValue() (interface{}, bool, error) {
	tok, err := p.next()
	if err != nil {
		return nil, false, err
	}
	v, err := p.valueFromToken(tok)
	if err != nil {
		return nil, false, err
	}
	if _, isNo := v.(hclNoValue); isNo {
		return nil, false, nil
	}
	return v, true, nil
}

func (p *hclParser) valueFromToken(tok hclToken) (interface{}, error) {
	switch tok.typ {
	case hTokEOF:
		return hclNoValue{}, nil
	case hTokString:
		return tok.text, nil
	case hTokBool:
		return tok.text == "true", nil
	case hTokNumber, hTokFloat:
		return parseHCLNumber(tok.text, false)
	case hTokSub:
		nt, err := p.next()
		if err != nil {
			return nil, err
		}
		if nt.typ == hTokNumber || nt.typ == hTokFloat {
			return parseHCLNumber(nt.text, true)
		}
		// Unknown token error refers to the '-' token.
		return nil, unknownTokenErr(tok)
	case hTokLBrack:
		return p.parseList()
	case hTokLBrace:
		return p.parseObjectList(true)
	}
	return nil, unknownTokenErr(tok)
}

func unknownTokenErr(tok hclToken) error {
	return atErr(tok, "Unknown token: %d:%d %s %s", tok.line, tok.col, tok.typ.Name(), tok.text)
}

func parseHCLNumber(text string, neg bool) (interface{}, error) {
	if strings.ContainsAny(text, ".eE") && !isHexNumber(text) {
		f, err := strconv.ParseFloat(applyNeg(text, neg), 64)
		if err != nil {
			return nil, err
		}
		return f, nil
	}
	// Integer with base detection (0x, leading 0 octal).
	s := applyNeg(text, neg)
	i, err := strconv.ParseInt(s, 0, 64)
	if err != nil {
		return nil, err
	}
	return i, nil
}

func isHexNumber(s string) bool {
	if strings.HasPrefix(s, "-") || strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	return strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X")
}

func applyNeg(text string, neg bool) string {
	if neg {
		return "-" + text
	}
	return text
}

func (p *hclParser) parseList() (interface{}, error) {
	elems := []interface{}{}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.typ == hTokEOF {
			return nil, atErr(tok, "unexpected token while parsing list: EOF")
		}
		if tok.typ == hTokRBrack {
			_, _ = p.next()
			return elems, nil
		}
		if tok.typ == hTokComma {
			_, _ = p.next()
			continue
		}
		// Parse an element.
		nt, err := p.next()
		if err != nil {
			return nil, err
		}
		var elem interface{}
		switch nt.typ {
		case hTokString, hTokBool, hTokNumber, hTokFloat, hTokSub, hTokLBrack, hTokLBrace:
			v, err := p.valueFromToken(nt)
			if err != nil {
				return nil, err
			}
			elem = v
		default:
			return nil, atErr(nt, "unexpected token while parsing list: %s", nt.typ.Name())
		}
		elems = append(elems, elem)
		// After element, expect comma or ]
		after, err := p.peek()
		if err != nil {
			return nil, err
		}
		if after.typ == hTokComma || after.typ == hTokRBrack {
			continue
		}
		if after.typ == hTokEOF {
			return nil, atErr(after, "unexpected token while parsing list: EOF")
		}
		return nil, atErr(after, "error parsing list, expected comma or list end, got: %s", after.typ.Name())
	}
}

func parseHCL(data []byte, opts *options) (interface{}, error) {
	lex := newHCLLexer(string(data))
	p := &hclParser{lex: lex}
	obj, err := p.parseTop()
	if err != nil {
		return nil, err
	}
	converted, err := convertHCLObject(obj)
	if err != nil {
		return nil, err
	}
	return converted, nil
}

// Conversion from HCL object syntax to the ordered map.

func convertHCLObject(obj *hclObject) (*OrderedMap, error) {
	m := &OrderedMap{}
	for _, item := range obj.items {
		if !item.hasValue {
			continue
		}
		if err := insertHCL(m, item.keys, item.value); err != nil {
			return nil, err
		}
	}
	return m, nil
}

func convertHCLValue(v interface{}) (interface{}, error) {
	switch t := v.(type) {
	case *hclObject:
		return convertHCLObject(t)
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, e := range t {
			cv, err := convertHCLValue(e)
			if err != nil {
				return nil, err
			}
			out[i] = cv
		}
		return out, nil
	default:
		return t, nil
	}
}

func insertHCL(m *OrderedMap, keys []string, raw interface{}) error {
	if len(keys) == 0 {
		return fmt.Errorf("empty key at line 0")
	}
	key := keys[0]
	if len(keys) > 1 {
		// Label path: descend into the last element under this key.
		for i, pr := range m.Pairs {
			if pr.Key == key {
				list, ok := pr.Value.([]interface{})
				if !ok {
					// Create the intermediate representation to report.
					inner := &OrderedMap{}
					if err := insertHCL(inner, keys[1:], raw); err != nil {
						return err
					}
					return fmt.Errorf("cannot append '%s' to '%s", hclRepr(inner), hclRepr(pr.Value))
				}
				if len(list) == 0 {
					child := &OrderedMap{}
					m.Pairs[i].Value = append(list, child)
					return insertHCL(child, keys[1:], raw)
				}
				if child, ok := list[len(list)-1].(*OrderedMap); ok {
					return insertHCL(child, keys[1:], raw)
				}
				inner := &OrderedMap{}
				if err := insertHCL(inner, keys[1:], raw); err != nil {
					return err
				}
				return fmt.Errorf("cannot append '%s' to '%s", hclRepr(inner), hclRepr(pr.Value))
			}
		}
		child := &OrderedMap{}
		m.Pairs = append(m.Pairs, Pair{key, []interface{}{child}})
		return insertHCL(child, keys[1:], raw)
	}

	// Single key.
	if obj, isObj := raw.(*hclObject); isObj {
		blockMap, err := convertHCLObject(obj)
		if err != nil {
			return err
		}
		return appendHCLBlock(m, key, blockMap)
	}
	if listRaw, isList := raw.([]interface{}); isList {
		converted, err := convertHCLValue(listRaw)
		if err != nil {
			return err
		}
		list := converted.([]interface{})
		return appendHCLList(m, key, list)
	}
	// Scalar (conversion of nested objects inside scalars doesn't occur).
	// But values may contain objects in lists; scalars here are plain.
	for i, pr := range m.Pairs {
		if pr.Key == key {
			if _, isList := pr.Value.([]interface{}); isList {
				return fmt.Errorf("cannot set '%s' over '%s'", hclRepr(raw), hclRepr(pr.Value))
			}
			m.Pairs[i].Value = raw
			return nil
		}
	}
	m.Pairs = append(m.Pairs, Pair{key, raw})
	return nil
}

func appendHCLBlock(m *OrderedMap, key string, block *OrderedMap) error {
	for i, pr := range m.Pairs {
		if pr.Key == key {
			if list, ok := pr.Value.([]interface{}); ok {
				m.Pairs[i].Value = append(list, block)
				return nil
			}
			return fmt.Errorf("cannot append '%s' to '%s", hclRepr(block), hclRepr(pr.Value))
		}
	}
	m.Pairs = append(m.Pairs, Pair{key, []interface{}{block}})
	return nil
}

func appendHCLList(m *OrderedMap, key string, list []interface{}) error {
	for i, pr := range m.Pairs {
		if pr.Key == key {
			if existing, ok := pr.Value.([]interface{}); ok {
				m.Pairs[i].Value = append(existing, list...)
				return nil
			}
			if len(list) > 0 {
				return fmt.Errorf("cannot append '%s' to '%s", hclRepr(list[0]), hclRepr(pr.Value))
			}
			return nil
		}
	}
	if len(list) == 0 {
		return nil
	}
	cp := make([]interface{}, len(list))
	copy(cp, list)
	m.Pairs = append(m.Pairs, Pair{key, cp})
	return nil
}

// hclRepr renders a value as Go's %#v would for the internal ordered-map
// types used by the original program (for error messages).
func hclRepr(v interface{}) string {
	switch t := v.(type) {
	case *OrderedMap:
		if t == nil || len(t.Pairs) == 0 {
			return "order.MapSlice{}"
		}
		parts := make([]string, len(t.Pairs))
		for i, p := range t.Pairs {
			parts[i] = fmt.Sprintf("order.MapItem{Key:%s, Val:%s}", strconv.Quote(p.Key), hclRepr(p.Value))
		}
		return "order.MapSlice{" + strings.Join(parts, ", ") + "}"
	case []interface{}:
		parts := make([]string, len(t))
		for i, e := range t {
			parts[i] = hclRepr(e)
		}
		return "[]interface {}{" + strings.Join(parts, ", ") + "}"
	case string:
		return strconv.Quote(t)
	default:
		return fmt.Sprintf("%#v", v)
	}
}
