package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"
)

// HCL AST used for encoding.
type hclOutItem struct {
	keys  []string
	value interface{} // *hclOutObject, *hclOutList, *hclScalar
}

type hclOutObject struct {
	items []*hclOutItem
}

type hclOutList struct {
	elems []interface{} // *hclScalar, *hclOutObject, *hclOutList
}

type hclScalar struct {
	kind string // STRING, NUMBER, FLOAT, BOOL, NULL
	text string // token text to print (empty for NULL)
}

func hclScalarFor(v interface{}, opts *options) *hclScalar {
	switch t := v.(type) {
	case nil:
		return &hclScalar{kind: "NULL", text: ""}
	case bool:
		if t {
			return &hclScalar{kind: "BOOL", text: "true"}
		}
		return &hclScalar{kind: "BOOL", text: "false"}
	case string:
		return &hclScalar{kind: "STRING", text: jsonString(t, false)}
	case int64:
		return &hclScalar{kind: "NUMBER", text: strconv.FormatInt(t, 10)}
	case uint64:
		return &hclScalar{kind: "NUMBER", text: strconv.FormatUint(t, 10)}
	case int:
		return &hclScalar{kind: "NUMBER", text: strconv.Itoa(t)}
	case float64:
		if math.IsInf(t, 1) {
			if opts.noConvert {
				return &hclScalar{kind: "FLOAT", text: marshalJSONFloat(math.MaxFloat64)}
			}
			return &hclScalar{kind: "STRING", text: jsonString("Infinity", false)}
		}
		if math.IsInf(t, -1) {
			if opts.noConvert {
				return &hclScalar{kind: "FLOAT", text: marshalJSONFloat(-math.MaxFloat64)}
			}
			return &hclScalar{kind: "STRING", text: jsonString("-Infinity", false)}
		}
		if math.IsNaN(t) {
			if opts.noConvert {
				return &hclScalar{kind: "NULL", text: ""}
			}
			return &hclScalar{kind: "STRING", text: jsonString("NaN", false)}
		}
		text := marshalJSONFloat(t)
		kind := "NUMBER"
		if strings.ContainsAny(text, ".eE") {
			kind = "FLOAT"
		}
		return &hclScalar{kind: kind, text: text}
	case time.Time:
		return &hclScalar{kind: "STRING", text: jsonString(formatTimeRFC3339(t), false)}
	default:
		return &hclScalar{kind: "STRING", text: jsonString(fmt.Sprintf("%v", t), false)}
	}
}

// objectFromMap builds an HCL object from an OrderedMap without flattening.
func objectFromMap(m *OrderedMap, opts *options) (*hclOutObject, error) {
	obj := &hclOutObject{}
	if m == nil {
		return obj, nil
	}
	for _, p := range m.Pairs {
		item, err := itemFromPair(p, opts)
		if err != nil {
			return nil, err
		}
		obj.items = append(obj.items, item...)
	}
	return obj, nil
}

// itemFromPair creates (possibly expanded) items for one map entry.
func itemFromPair(p Pair, opts *options) ([]*hclOutItem, error) {
	items, err := expandValueForItem([]string{p.Key}, p.Value, opts)
	if err != nil {
		return nil, err
	}
	return items, nil
}

// expandValueForItem returns items for keys->value, handling lists of
// objects and object flattening.
func expandValueForItem(keys []string, v interface{}, opts *options) ([]*hclOutItem, error) {
	switch t := v.(type) {
	case *OrderedMap:
		return expandObjectItem(keys, t, opts)
	case []interface{}:
		return expandListItem(keys, t, opts)
	default:
		return []*hclOutItem{{keys: keys, value: hclScalarFor(v, opts)}}, nil
	}
}

// expandObjectItem handles an item whose value is a map.
func expandObjectItem(keys []string, m *OrderedMap, opts *options) ([]*hclOutItem, error) {
	// Build the inner items (expanded each sub-entry without parent explosion first)
	// Determine original all-objects before list expansion.
	allObject := len(m.Pairs) > 0
	for _, p := range m.Pairs {
		if _, ok := p.Value.(*OrderedMap); !ok {
			allObject = false
			break
		}
	}
	// Inner expanded items
	innerItems := []*hclOutItem{}
	for _, p := range m.Pairs {
		sub, err := expandValueForItem([]string{p.Key}, p.Value, opts)
		if err != nil {
			return nil, err
		}
		innerItems = append(innerItems, sub...)
	}
	if allObject {
		var out []*hclOutItem
		for _, sub := range innerItems {
			combinedKeys := append(append([]string{}, keys...), sub.keys...)
			out = append(out, &hclOutItem{keys: combinedKeys, value: sub.value})
		}
		return out, nil
	}
	return []*hclOutItem{{keys: keys, value: &hclOutObject{items: innerItems}}}, nil
}

// expandListItem handles an item whose value is a list.
func expandListItem(keys []string, list []interface{}, opts *options) ([]*hclOutItem, error) {
	if err := checkListNulls(list); err != nil {
		return nil, err
	}
	// Single-element lists that wrap a list are unwrapped.
	if len(list) == 1 {
		if inner, ok := list[0].([]interface{}); ok {
			return expandListItem(keys, inner, opts)
		}
	}
	if len(list) > 1 {
		if _, firstIsList := list[0].([]interface{}); firstIsList {
			// Mimics an error from the HCL JSON parser.
			second := list[1]
			return nil, fmt.Errorf("expected: STRING got: %s", tokenKindForError(second, opts))
		}
	}
	if len(list) > 0 {
		allMaps := true
		for _, e := range list {
			if _, ok := e.(*OrderedMap); !ok {
				allMaps = false
				break
			}
		}
		if allMaps {
			var out []*hclOutItem
			for _, e := range list {
				sub, err := expandObjectItem(keys, e.(*OrderedMap), opts)
				if err != nil {
					return nil, err
				}
				out = append(out, sub...)
			}
			return out, nil
		}
	}
	// Ordinary list.
	hl := &hclOutList{}
	for _, e := range list {
		elem, err := listElement(e, opts)
		if err != nil {
			return nil, err
		}
		if elem != nil {
			hl.elems = append(hl.elems, elem)
		}
	}
	return []*hclOutItem{{keys: keys, value: hl}}, nil
}

func checkListNulls(list []interface{}) error {
	for _, e := range list {
		if e == nil {
			return fmt.Errorf("unexpected token while parsing list: NULL")
		}
		if sub, ok := e.([]interface{}); ok {
			if err := checkListNulls(sub); err != nil {
				return err
			}
		}
	}
	return nil
}

func tokenKindForError(v interface{}, opts *options) string {
	switch t := v.(type) {
	case nil:
		return "NULL"
	case string:
		return "STRING"
	case bool:
		return "BOOL"
	case []interface{}:
		return "LBRACK"
	case *OrderedMap:
		return "STRING"
	default:
		s := hclScalarFor(v, opts)
		return s.kind
	}
}

// listElement converts an element inside an ordinary (non-object) list.
// Returns nil,nil for a dropped element.
func listElement(v interface{}, opts *options) (interface{}, error) {
	switch t := v.(type) {
	case nil:
		return nil, fmt.Errorf("unexpected token while parsing list: NULL")
	case bool:
		// Booleans are dropped from lists.
		return nil, nil
	case *OrderedMap:
		// Object inside a list: its entries are processed as object items.
		obj := &hclOutObject{}
		for _, p := range t.Pairs {
			sub, err := expandValueForItem([]string{p.Key}, p.Value, opts)
			if err != nil {
				return nil, err
			}
			obj.items = append(obj.items, sub...)
		}
		return obj, nil
	case []interface{}:
		// Flatten nested list elements.
		return nil, fmt.Errorf("internal list flatten handled by caller")
	default:
		return hclScalarFor(v, opts), nil
	}
}

// flattenListElements builds list elements with nested flattening.
func buildList(list []interface{}, opts *options) (*hclOutList, error) {
	hl := &hclOutList{}
	var add func(vals []interface{}) error
	add = func(vals []interface{}) error {
		for _, e := range vals {
			if sub, ok := e.([]interface{}); ok {
				if err := checkListNulls(sub); err != nil {
					return err
				}
				if err := add(sub); err != nil {
					return err
				}
				continue
			}
			elem, err := listElement(e, opts)
			if err != nil {
				return err
			}
			if elem != nil {
				hl.elems = append(hl.elems, elem)
			}
		}
		return nil
	}
	if err := add(list); err != nil {
		return nil, err
	}
	return hl, nil
}

func encodeHCL(v interface{}, opts *options) ([]byte, error) {
	m, ok := v.(*OrderedMap)
	if !ok {
		// Produce the top-level error from the HCL JSON parser.
		return nil, topLevelHCLError(v, opts)
	}
	obj, err := objectFromMap(m, opts)
	if err != nil {
		return nil, err
	}
	// Rebuild ordinary lists with proper flattening: patch list values that
	// were built without nested flattening.
	if err := patchLists(obj, opts); err != nil {
		return nil, err
	}
	out := printHCLObject(obj, 0)
	return []byte(out), nil
}

func patchLists(obj *hclOutObject, opts *options) error {
	// Our expandListItem already handles the ordinary-list construction but
	// nested lists are flattened there via listElement error avoidance:
	// rebuild any HclOutList by re-deriving from stored elements is not
	// needed; nested lists were single-unwrapped or rejected.
	return nil
}

func topLevelHCLError(v interface{}, opts *options) error {
	switch t := v.(type) {
	case nil:
		return fmt.Errorf("Expected object, got unknown token: 1:1 NULL null")
	case string:
		return fmt.Errorf("Expected object, got unknown token: 1:1 STRING %s", jsonString(t, false))
	case bool:
		return fmt.Errorf("Expected object, got unknown token: 1:1 BOOL %v", t)
	case []interface{}:
		return fmt.Errorf("Expected object, got unknown token: 1:1 LBRACK [")
	default:
		s := hclScalarFor(v, opts)
		return fmt.Errorf("Expected object, got unknown token: 1:1 %s %s", s.kind, s.text)
	}
}

func printHCLObject(obj *hclOutObject, indent int) string {
	parts := make([]string, 0, len(obj.items))
	for _, item := range obj.items {
		parts = append(parts, printHCLItem(item, indent))
	}
	return strings.Join(parts, "\n\n")
}

func quotedKey(k string) string {
	return jsonString(k, false)
}

func printHCLItem(item *hclOutItem, indent int) string {
	pad := strings.Repeat("  ", indent)
	keys := make([]string, len(item.keys))
	for i, k := range item.keys {
		keys[i] = quotedKey(k)
	}
	joined := strings.Join(keys, " ")
	switch val := item.value.(type) {
	case *hclScalar:
		return fmt.Sprintf("%s%s = %s", pad, joined, val.text)
	case *hclOutObject:
		if len(item.keys) > 1 {
			if len(val.items) == 0 {
				return fmt.Sprintf("%s%s {}", pad, joined)
			}
			inner := printHCLObject(val, indent+1)
			return fmt.Sprintf("%s%s {\n%s\n%s}", pad, joined, inner, pad)
		}
		if len(val.items) == 0 {
			return fmt.Sprintf("%s%s = {}", pad, joined)
		}
		inner := printHCLObject(val, indent+1)
		return fmt.Sprintf("%s%s = {\n%s\n%s}", pad, joined, inner, pad)
	case *hclOutList:
		return fmt.Sprintf("%s%s = %s", pad, joined, printHCLList(val, indent))
	}
	return ""
}

func printHCLList(l *hclOutList, indent int) string {
	hasObject := false
	for _, e := range l.elems {
		if _, ok := e.(*hclOutObject); ok {
			hasObject = true
			break
		}
	}
	if !hasObject {
		parts := make([]string, len(l.elems))
		for i, e := range l.elems {
			parts[i] = printHCLListElem(e, indent)
		}
		return "[" + strings.Join(parts, ", ") + "]"
	}
	pad := strings.Repeat("  ", indent)
	innerPad := strings.Repeat("  ", indent+1)
	var b strings.Builder
	b.WriteString("[\n")
	for _, e := range l.elems {
		b.WriteString(innerPad)
		b.WriteString(printHCLListElem(e, indent+1))
		b.WriteString(",\n")
	}
	b.WriteString(pad)
	b.WriteString("]")
	return b.String()
}

func printHCLListElem(e interface{}, indent int) string {
	switch t := e.(type) {
	case *hclScalar:
		return t.text
	case *hclOutObject:
		pad := strings.Repeat("  ", indent)
		if len(t.items) == 0 {
			return "{}"
		}
		inner := printHCLObject(t, indent+1)
		return fmt.Sprintf("{\n%s\n%s}", inner, pad)
	case *hclOutList:
		return printHCLList(t, indent)
	}
	return ""
}
EOF

