	var add func(vals []interface{}) error
	add = func(vals []interface{}) error {
		for _, e := range vals {
			if sub, ok := e.([]interface{}); ok {
				if err := checkListNulls(sub); err != nil {
					return err
				}
				if err := add(sub); err != nil {
					return err
				}
				continue
			}
			elem, err := listElement(e, opts)
			if err != nil {
				return err
			}
			if elem != nil {
				hl.elems = append(hl.elems, elem)
			}
		}
		return nil
	}
	if err := add(list); err != nil {
		return nil, err
	}
	return hl, nil
}

func encodeHCL(v interface{}, opts *options) ([]byte, error) {
	m, ok := v.(*OrderedMap)
	if !ok {
		// Produce the top-level error from the HCL JSON parser.
		return nil, topLevelHCLError(v, opts)
	}
	obj, err := objectFromMap(m, opts)
	if err != nil {
		return nil, err
	}
	// Rebuild ordinary lists with proper flattening: patch list values that
	// were built without nested flattening.
	if err := patchLists(obj, opts); err != nil {
		return nil, err
	}
	out := printHCLObject(obj, 0)
	return []byte(out), nil
}

func patchLists(obj *hclOutObject, opts *options) error {
	// Our expandListItem already handles the ordinary-list construction but
	// nested lists are flattened there via listElement error avoidance:
	// rebuild any HclOutList by re-deriving from stored elements is not
	// needed; nested lists were single-unwrapped or rejected.
	return nil
}

func topLevelHCLError(v interface{}, opts *options) error {
	switch t := v.(type) {
	case nil:
		return fmt.Errorf("Expected object, got unknown token: 1:1 NULL null")
	case string:
		return fmt.Errorf("Expected object, got unknown token: 1:1 STRING %s", jsonString(t, false))
	case bool:
		return fmt.Errorf("Expected object, got unknown token: 1:1 BOOL %v", t)
	case []interface{}:
		return fmt.Errorf("Expected object, got unknown token: 1:1 LBRACK [")
	default:
		s := hclScalarFor(v, opts)
		return fmt.Errorf("Expected object, got unknown token: 1:1 %s %s", s.kind, s.text)
	}
}

func printHCLObject(obj *hclOutObject, indent int) string {
	parts := make([]string, 0, len(obj.items))
	for _, item := range obj.items {
		parts = append(parts, printHCLItem(item, indent))
	}
	return strings.Join(parts, "\n\n")
}

func quotedKey(k string) string {
	return jsonString(k, false)
}

func printHCLItem(item *hclOutItem, indent int) string {
	pad := strings.Repeat("  ", indent)
	keys := make([]string, len(item.keys))
	for i, k := range item.keys {
		keys[i] = quotedKey(k)
	}
	joined := strings.Join(keys, " ")
	switch val := item.value.(type) {
	case *hclScalar:
		return fmt.Sprintf("%s%s = %s", pad, joined, val.text)
	case *hclOutObject:
		if len(item.keys) > 1 {
			if len(val.items) == 0 {
				return fmt.Sprintf("%s%s {}", pad, joined)
			}
			inner := printHCLObject(val, indent+1)
			return fmt.Sprintf("%s%s {\n%s\n%s}", pad, joined, inner, pad)
		}
		if len(val.items) == 0 {
			return fmt.Sprintf("%s%s = {}", pad, joined)
		}
		inner := printHCLObject(val, indent+1)
		return fmt.Sprintf("%s%s = {\n%s\n%s}", pad, joined, inner, pad)
	case *hclOutList:
		return fmt.Sprintf("%s%s = %s", pad, joined, printHCLList(val, indent))
	}
	return ""
}

func printHCLList(l *hclOutList, indent int) string {
	hasObject := false
	for _, e := range l.elems {
		if _, ok := e.(*hclOutObject); ok {
			hasObject = true
			break
		}
	}
	if !hasObject {
		parts := make([]string, len(l.elems))
		for i, e := range l.elems {
			parts[i] = printHCLListElem(e, indent)
		}
		return "[" + strings.Join(parts, ", ") + "]"
	}
	pad := strings.Repeat("  ", indent)
	innerPad := strings.Repeat("  ", indent+1)
	var b strings.Builder
	b.WriteString("[\n")
	for _, e := range l.elems {
		b.WriteString(innerPad)
		b.WriteString(printHCLListElem(e, indent+1))
		b.WriteString(",\n")
	}
	b.WriteString(pad)
	b.WriteString("]")
	return b.String()
}

func printHCLListElem(e interface{}, indent int) string {
	switch t := e.(type) {
	case *hclScalar:
		return t.text
	case *hclOutObject:
		pad := strings.Repeat("  ", indent)
		if len(t.items) == 0 {
			return "{}"
		}
		inner := printHCLObject(t, indent+1)
		return fmt.Sprintf("{\n%s\n%s}", inner, pad)
	case *hclOutList:
		return printHCLList(t, indent)
	}
	return ""
}
EOF
"}

