{"command":"cat > main.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

const version = "0.0.0"

func usageString(prog string) string {
	return fmt.Sprintf(`Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version

`, prog)
}

func main() {
	os.Exit(run(os.Args, os.Stdin, os.Stdout, os.Stderr))
}

func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	prog := ""
	if len(args) > 0 {
		prog = args[0]
	}
	usage := usageString(prog)

	// Concatenate all flag arguments, ignoring '-', ' ' and '\t'.
	var flagRunes []rune
	var invalid []string
	valid := map[rune]bool{
		'y': true, 't': true, 'j': true, 'c': true, 'r': true,
		'n': true, 'e': true, 'i': true, 'k': true, 'h': true, 'v': true,
	}
	for _, arg := range args[1:] {
		for _, r := range arg {
			if r == '-' || r == ' ' || r == '\t' {
				continue
			}
			if !valid[r] {
				invalid = append(invalid, string(r))
			}
			flagRunes = append(flagRunes, r)
		}
	}
	if len(invalid) > 0 {
		fmt.Fprint(stderr, usage)
		fmt.Fprintf(stderr, "Error: invalid flags specified: %s\n", strings.Join(invalid, " "))
		return 1
	}

	opts := &options{}
	contains := func(r rune) bool {
		for _, x := range flagRunes {
			if x == r {
				return true
			}
		}
		return false
	}
	opts.noConvert = contains('n')
	opts.escapeHTML = contains('e')
	opts.indent = contains('i')
	opts.parseKeys = contains('k')

	// Determine conversion from the format characters.
	var formats []Format
	for _, r := range flagRunes {
		switch r {
		case 'y':
			formats = append(formats, FormatYAML)
		case 't':
			formats = append(formats, FormatTOML)
		case 'j':
			formats = append(formats, FormatJSON)
		case 'c':
			formats = append(formats, FormatHCL)
		case 'r':
			formats = append(formats, FormatJSON, FormatYAML)
		}
	}
	if len(formats) == 0 {
		opts.source = FormatYAML
		opts.target = FormatJSON
	} else if len(formats) == 1 {
		opts.source = formats[0]
		opts.target = FormatJSON
	} else {
		opts.source = formats[len(formats)-2]
		opts.target = formats[len(formats)-1]
	}

	// Validate output-dependent flags in k, e, i order.
	if opts.parseKeys && opts.target != FormatYAML {
		fmt.Fprint(stderr, usage)
		fmt.Fprintf(stderr, "Error: flag -k only valid for YAML output\n")
		return 1
	}
	if opts.escapeHTML && opts.target != FormatJSON {
		fmt.Fprint(stderr, usage)
		fmt.Fprintf(stderr, "Error: flag -e only valid for JSON output\n")
		return 1
	}
	if opts.indent && opts.target != FormatJSON && opts.target != FormatTOML {
		fmt.Fprint(stderr, usage)
		fmt.Fprintf(stderr, "Error: flag -i only valid for JSON or TOML output\n")
		return 1
	}

	if contains('h') {
		fmt.Fprint(stdout, usage)
		return 0
	}
	if contains('v') {
		fmt.Fprintf(stdout, "v%s\n", version)
		return 0
	}

	data, _ := io.ReadAll(stdin)

	var value interface{}
	var err error
	switch opts.source {
	case FormatYAML:
		value, err = parseYAML(data, opts)
	case FormatTOML:
		value, err = parseTOML(data, opts)
	case FormatJSON:
		value, err = parseJSON(data, opts)
	case FormatHCL:
		value, err = parseHCL(data, opts)
	}
	if err != nil {
		fmt.Fprintf(stderr, "Error parsing %s: %s\n", opts.source.Name(), err.Error())
		return 1
	}

	if _, isEmpty := value.(emptyDocument); isEmpty {
		return 0
	}

	var out []byte
	switch opts.target {
	case FormatJSON:
		out, err = encodeJSON(value, opts)
	case FormatYAML:
		out, err = encodeYAML(value, opts)
	case FormatTOML:
		out, err = encodeTOML(value, opts)
	case FormatHCL:
		out, err = encodeHCL(value, opts)
	}
	if err != nil {
		fmt.Fprintf(stderr, "Error writing %s: %s\n", opts.target.Name(), err.Error())
		return 1
	}
	_, _ = stdout.Write(out)
	return 0
}
EOF
