	case FormatHCL:
		value, err = parseHCL(data, opts)
	}
	if err != nil {
		fmt.Fprintf(stderr, "Error parsing %s: %s\n", opts.source.Name(), err.Error())
		return 1
	}

	if _, isEmpty := value.(emptyDocument); isEmpty {
		return 0
	}

	var out []byte
	switch opts.target {
	case FormatJSON:
		out, err = encodeJSON(value, opts)
	case FormatYAML:
		out, err = encodeYAML(value, opts)
	case FormatTOML:
		out, err = encodeTOML(value, opts)
	case FormatHCL:
		out, err = encodeHCL(value, opts)
	}
	if err != nil {
		fmt.Fprintf(stderr, "Error writing %s: %s\n", opts.target.Name(), err.Error())
		return 1
	}
	_, _ = stdout.Write(out)
	return 0
