def classify(flag):
    o,e,c=run("./executable",[flag],garbage)
    tail=e.splitlines()[-1] if e.strip() else ""
    inf=None
    for name in ["YAML","TOML","JSON","HCL"]:
        if f"parsing {name}" in tail: inf=name
    if inf is None:
        return f"{flag} err={tail!r} out={o!r}"
