	hjComma
	hjString
	hjNumber
	hjFloat
	hjBool
	hjNull
	hjIdent
)

func (t hjTokType) Name() string {
	switch t {
	case hjEOF:
		return "EOF"
	case hjLBrace:
		return "OBJECT"
	case hjRBrace:
		return "RBRACE"
	case hjLBrack:
		return "LBRACK"
	case hjRBrack:
		return "RBRACK"
	case hjColon:
		return "COLON"
	case hjComma:
		return "COMMA"
	case hjString:
		return "STRING"
	case hjNumber:
		return "NUMBER"
	case hjFloat:
		return "FLOAT"
	case hjBool:
		return "BOOL"
	case hjNull:
		return "NULL"
	case hjIdent:
		return "IDENT"
	}
	return "EOF"
}

type hjToken struct {
	typ  hjTokType
	raw  string
	line int
	col  int
}

type hjLexer struct {
	input string
	pos   int
	line  int
	col   int
}

func (l *hjLexer) errf(line, col int, format string, args ...interface{}) error {
	return fmt.Errorf("%d:%d: %s", line, col, fmt.Sprintf(format, args...))
}

func (l *hjLexer) peekRune() (rune, int) {
	if l.pos >= len(l.input) {
		return utf8.RuneError, 0
	}
	return utf8.DecodeRuneInString(l.input[l.pos:])
}

func (l *hjLexer) peekAt(off int) (rune, int) {
	if l.pos+off >= len(l.input) {
		return utf8.RuneError, 0
	}
	return utf8.DecodeRuneInString(l.input[l.pos+off:])
}

func (l *hjLexer) nextRune() rune {
	if l.pos >= len(l.input) {
		return utf8.RuneError
	}
	r, sz := utf8.DecodeRuneInString(l.input[l.pos:])
	l.pos += sz
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}

func (l *hjLexer) next() (hjToken, error) {
	for l.pos < len(l.input) {
		r, _ := l.peekRune()
		if r == ' ' || r == '\t' || r == '\r' || r == '\n' {
			l.nextRune()
			continue
		}
		break
	}
	line, col := l.line, l.col
	if l.pos >= len(l.input) {
		return hjToken{hjEOF, "", line, col}, nil
	}
	r, _ := l.peekRune()
	switch r {
	case '{':
		l.nextRune()
		return hjToken{hjLBrace, "{", line, col}, nil
	case '}':
		l.nextRune()
		return hjToken{hjRBrace, "}", line, col}, nil
	case '[':
		l.nextRune()
		return hjToken{hjLBrack, "[", line, col}, nil
	case ']':
		l.nextRune()
		return hjToken{hjRBrack, "]", line, col}, nil
	case ':':
		l.nextRune()
		return hjToken{hjColon, ":", line, col}, nil
	case ',':
		l.nextRune()
		return hjToken{hjComma, ",", line, col}, nil
	case '"':
		return l.scanString()
	case '-':
		// Number if followed by digit or dot, otherwise treat as ident-ish token.
		if r2, _ := l.peekAt(1); (r2 >= '0' && r2 <= '9') || r2 == '.' {
			return l.scanNumber()
		}
		return hjToken{}, l.errf(line, col, "illegal char")
	}
	if r >= '0' && r <= '9' || r == '.' {
		return l.scanNumber()
	}
	if r == '_' || unicode.IsLetter(r) {
		start := l.pos
		for l.pos < len(l.input) {
			c, _ := l.peekRune()
			if unicode.IsLetter(c) || unicode.IsDigit(c) || c == '_' || c == '-' {
				l.nextRune()
			} else {
				break
			}
		}
		text := l.input[start:l.pos]
		switch text {
		case "true", "false":
			return hjToken{hjBool, text, line, col}, nil
		case "null":
			return hjToken{hjNull, text, line, col}, nil
		}
		return hjToken{hjIdent, text, line, col}, nil
	}
	return hjToken{}, l.errf(line, col, "illegal char")
