	r, sz := utf8.DecodeRuneInString(l.input[l.pos:])
	l.pos += sz
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}

func (l *hjLexer) next() (hjToken, error) {
	for l.pos < len(l.input) {
		r, _ := l.peekRune()
		if r == ' ' || r == '\t' || r == '\r' || r == '\n' {
			l.nextRune()
			continue
		}
		break
	}
	line, col := l.line, l.col
	if l.pos >= len(l.input) {
		return hjToken{hjEOF, "", line, col}, nil
	}
	r, _ := l.peekRune()
	switch r {
	case '{':
		l.nextRune()
		return hjToken{hjLBrace, "{", line, col}, nil
	case '}':
		l.nextRune()
		return hjToken{hjRBrace, "}", line, col}, nil
	case '[':
		l.nextRune()
		return hjToken{hjLBrack, "[", line, col}, nil
	case ']':
		l.nextRune()
		return hjToken{hjRBrack, "]", line, col}, nil
	case ':':
		l.nextRune()
		return hjToken{hjColon, ":", line, col}, nil
	case ',':
		l.nextRune()
		return hjToken{hjComma, ",", line, col}, nil
	case '"':
		return l.scanString()
	case '-':
		// Number if followed by digit or dot, otherwise treat as ident-ish token.
		if r2, _ := l.peekAt(1); (r2 >= '0' && r2 <= '9') || r2 == '.' {
			return l.scanNumber()
		}
		return hjToken{}, l.errf(line, col, "illegal char")
	}
	if r >= '0' && r <= '9' || r == '.' {
		return l.scanNumber()
	}
	if r == '_' || unicode.IsLetter(r) {
		start := l.pos
		for l.pos < len(l.input) {
			c, _ := l.peekRune()
			if unicode.IsLetter(c) || unicode.IsDigit(c) || c == '_' || c == '-' {
				l.nextRune()
			} else {
				break
			}
		}
		text := l.input[start:l.pos]
		switch text {
		case "true", "false":
			return hjToken{hjBool, text, line, col}, nil
		case "null":
			return hjToken{hjNull, text, line, col}, nil
		}
		return hjToken{hjIdent, text, line, col}, nil
	}
	return hjToken{}, l.errf(line, col, "illegal char")
}

func (l *hjLexer) scanString() (hjToken, error) {
	line, col := l.line, l.col
	start := l.pos
	l.nextRune()
	for {
		if l.pos >= len(l.input) {
			return hjToken{}, l.errf(l.line, l.col, "literal not terminated")
		}
		c := l.nextRune()
		if c == '"' {
			return hjToken{hjString, l.input[start:l.pos], line, col}, nil
		}
		if c == '\n' {
			return hjToken{}, l.errf(l.line, l.col, "literal not terminated")
		}
		if c == '\\' {
			if l.pos >= len(l.input) {
				return hjToken{}, l.errf(l.line, l.col, "literal not terminated")
			}
			escLine, escCol := l.line, l.col
			e := l.nextRune()
			switch e {
			case 'n', 'r', 't', 'b', 'f', 'v', '"', '\\':
			case 'u', 'U':
				n := 4
				if e == 'U' {
					n = 8
				}
				for i := 0; i < n; i++ {
					h := l.nextRune()
					if _, ok := hexVal(h); !ok {
						return hjToken{}, l.errf(l.line, l.col, "literal not terminated")
					}
				}
			default:
				return hjToken{}, l.errf(escLine, escCol, "illegal char escape")
			}
		}
	}
}

func (l *hjLexer) scanNumber() (hjToken, error) {
	line, col := l.line, l.col
	start := l.pos
	if r, _ := l.peekRune(); r == '-' {
		l.nextRune()
	}
	isFloat := false
	if r, _ := l.peekRune(); r == '.' {
		isFloat = true
		l.nextRune()
		for {
			if c, _ := l.peekRune(); c >= '0' && c <= '9' {
				l.nextRune()
			} else {
				break
			}
		}
	} else {
		// Check leading zero.
		if r, _ := l.peekRune(); r == '0' {
			l.nextRune()
			if c, _ := l.peekRune(); c >= '0' && c <= '9' {
				return hjToken{}, l.errf(l.line, l.col, "numbers cannot start with 0")
			}
		} else {
			for {
				if c, _ := l.peekRune(); c >= '0' && c <= '9' {
					l.nextRune()
				} else {
					break
				}
			}
		}
		if c, _ := l.peekRune(); c == '.' {
			isFloat = true
			l.nextRune()
			for {
				if c2, _ := l.peekRune(); c2 >= '0' && c2 <= '9' {
					l.nextRune()
				} else {
					break
				}
			}
		}
	}
	if c, _ := l.peekRune(); c == 'e' || c == 'E' {
		isFloat = true
		l.nextRune()
		if c2, _ := l.peekRune(); c2 == '+' || c2 == '-' {
			l.nextRune()
		}
		for {
			if c2, _ := l.peekRune(); c2 >= '0' && c2 <= '9' {
				l.nextRune()
			} else {
				break
			}
		}
	}
	typ := hjNumber
	if isFloat {
		typ = hjFloat
	}
	return hjToken{typ, l.input[start:l.pos], line, col}, nil
}

type hjParser struct {
	lex     *hjLexer
	peeked  *hjToken
	peekErr error
	hasPeek bool
}

func (p *hjParser) peek() (hjToken, error) {
	if p.hasPeek {
		return *p.peeked, p.peekErr
	}
	t, err := p.lex.next()
	p.peeked = &t
	p.peekErr = err
	p.hasPeek = true
	return t, err
}

func (p *hjParser) next() (hjToken, error) {
	if p.hasPeek {
		t := *p.peeked
		err := p.peekErr
		p.hasPeek = false
		p.peeked = nil
		p.peekErr = nil
		return t, err
	}
	return p.lex.next()
}

func unquoteHJ(t hjToken) (string, error) {
	s, err := strconv.Unquote(t.raw)
	if err != nil {
		return "", fmt.Errorf("unexpected failure: unquote %q err: %v", t.raw, err)
	}
	return s, nil
}

func (p *hjParser) parseObject() (*OrderedMap, error) {
	// Consume '{'
	if _, err := p.next(); err != nil {
		return nil, err
	}
	m := &OrderedMap{}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.typ == hjEOF {
			return m, nil
		}
		if tok.typ == hjRBrace {
			_, _ = p.next()
			return m, nil
		}
		if tok.typ == hjComma {
			_, _ = p.next()
			continue
		}
		if tok.typ != hjString {
			return nil, fmt.Errorf("expected: STRING got: %s", tok.typ.Name())
		}
		kt, _ := p.next()
		key, err := unquoteHJ(kt)
		if err != nil {
			return nil, err
		}
		// colon
		ct, err := p.peek()
		if err != nil {
			return nil, err
		}
		if ct.typ == hjColon {
			_, _ = p.next()
		} else if ct.typ == hjComma || ct.typ == hjRBrace || ct.typ == hjEOF {
			continue
		} else {
			return nil, fmt.Errorf("expected: COLON got: %s", ct.typ.Name())
		}
		// Value may be missing.
		vt, err := p.peek()
		if err != nil {
			return nil, err
		}
		if vt.typ == hjComma || vt.typ == hjRBrace || vt.typ == hjEOF {
			continue
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		m.Pairs = append(m.Pairs, Pair{key, v})
	}
}

func (p *hjParser) parseValue() (interface{}, error) {
	tok, err := p.next()
	if err != nil {
		return nil, err
	}
	switch tok.typ {
	case hjString:
		return unquoteHJ(tok)
	case hjBool:
		return tok.raw == "true", nil
	case hjNull:
		return hclJSONNull{}, nil
	case hjNumber:
		i, err := strconv.ParseInt(tok.raw, 10, 64)
		if err != nil {
			return nil, err
		}
		return i, nil
	case hjFloat:
		f, err := strconv.ParseFloat(tok.raw, 64)
		if err != nil {
			return nil, err
		}
		return f, nil
	case hjLBrace:
		// Rewind by using a sub-parser trick: we have consumed the brace.
		// Parse the object contents manually.
		p.hasPeek = true
		t := tok
		p.peeked = &t
		p.peekErr = nil
		return p.parseObject()
	case hjLBrack:
		return p.parseListRest()
	}
	return nil, fmt.Errorf("Unknown token: %d:%d %s %s", tok.line, tok.col, tok.typ.Name(), tok.raw)
}

func (p *hjParser) parseListRest() (interface{}, error) {
	elems := []interface{}{}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.typ == hjEOF {
			return nil, fmt.Errorf("unexpected token while parsing list: EOF")
		}
		if tok.typ == hjRBrack {
			_, _ = p.next()
			return elems, nil
		}
		if tok.typ == hjComma {
			_, _ = p.next()
			continue
		}
		if tok.typ == hjNull {
			return nil, fmt.Errorf("unexpected token while parsing list: NULL")
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		elems = append(elems, v)
		after, err := p.peek()
		if err != nil {
			return nil, err
		}
		if after.typ == hjComma || after.typ == hjRBrack {
			continue
		}
		if after.typ == hjEOF {
			return nil, fmt.Errorf("unexpected token while parsing list: EOF")
		}
		return nil, fmt.Errorf("error parsing list, expected comma or list end, got: %s", after.typ.Name())
	}
}

func parseHCLJSON(data []byte, opts *options) (interface{}, error) {
	p := &hjParser{lex: &hjLexer{input: string(data), line: 1, col: 1}}
	obj, err := p.parseObject()
	if err != nil {
		return nil, err
	}
	return convertHCLJSONObject(obj)
}

func convertHCLJSONObject(obj *OrderedMap) (*OrderedMap, error) {
	m := &OrderedMap{}
	for _, pair := range obj.Pairs {
		if err := insertHCLJSON(m, pair.Key, pair.Value); err != nil {
			return nil, err
		}
	}
	return m, nil
}

func insertHCLJSON(m *OrderedMap, key string, v interface{}) error {
	switch t := v.(type) {
	case *OrderedMap:
		block, err := convertHCLJSONObject(t)
		if err != nil {
			return err
		}
		return appendHCLBlock(m, key, block)
	case []interface{}:
		converted, err := convertHCLJSONList(t)
		if err != nil {
			return err
		}
		return appendHCLList(m, key, converted)
	case hclJSONNull:
		// Scalar null becomes an empty string.
		for i, pr := range m.Pairs {
			if pr.Key == key {
				if _, isList := pr.Value.([]interface{}); isList {
					return fmt.Errorf("cannot set '%s' over '%s'", hclRepr(""), hclRepr(pr.Value))
				}
				m.Pairs[i].Value = ""
				return nil
			}
		}
		m.Pairs = append(m.Pairs, Pair{key, ""})
		return nil
	default:
		for i, pr := range m.Pairs {
			if pr.Key == key {
				if _, isList := pr.Value.([]interface{}); isList {
					return fmt.Errorf("cannot set '%s' over '%s'", hclRepr(v), hclRepr(pr.Value))
				}
				m.Pairs[i].Value = v
				return nil
			}
		}
		m.Pairs = append(m.Pairs, Pair{key, v})
		return nil
	}
}

func convertHCLJSONList(list []interface{}) ([]interface{}, error) {
	out := []interface{}{}
	for _, e := range list {
		switch t := e.(type) {
		case *OrderedMap:
			cm, err := convertHCLJSONObject(t)
			if err != nil {
				return nil, err
			}
			out = append(out, cm)
		case []interface{}:
			flat, err := convertHCLJSONList(t)
			if err != nil {
				return nil, err
			}
			out = append(out, flat...)
		case bool:
			// Dropped.
		case hclJSONNull:
			return nil, fmt.Errorf("unexpected token while parsing list: NULL")
		default:
			out = append(out, e)
		}
	}
	return out, nil
}

