	return t, err
}

func (p *hjParser) next() (hjToken, error) {
	if p.hasPeek {
		t := *p.peeked
		err := p.peekErr
		p.hasPeek = false
		p.peeked = nil
		p.peekErr = nil
		return t, err
	}
	return p.lex.next()
}

func unquoteHJ(t hjToken) (string, error) {
	s, err := strconv.Unquote(t.raw)
	if err != nil {
		return "", fmt.Errorf("unexpected failure: unquote %q err: %v", t.raw, err)
	}
	return s, nil
}

func (p *hjParser) parseObject() (*OrderedMap, error) {
	// Consume '{'
	if _, err := p.next(); err != nil {
		return nil, err
	}
	m := &OrderedMap{}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.typ == hjEOF {
			return m, nil
		}
		if tok.typ == hjRBrace {
			_, _ = p.next()
			return m, nil
		}
		if tok.typ == hjComma {
			_, _ = p.next()
			continue
		}
		if tok.typ != hjString {
			return nil, fmt.Errorf("expected: STRING got: %s", tok.typ.Name())
		}
		kt, _ := p.next()
		key, err := unquoteHJ(kt)
		if err != nil {
			return nil, err
		}
		// colon
		ct, err := p.peek()
		if err != nil {
			return nil, err
		}
		if ct.typ == hjColon {
			_, _ = p.next()
		} else if ct.typ == hjComma || ct.typ == hjRBrace || ct.typ == hjEOF {
			continue
		} else {
			return nil, fmt.Errorf("expected: COLON got: %s", ct.typ.Name())
		}
		// Value may be missing.
		vt, err := p.peek()
		if err != nil {
			return nil, err
		}
		if vt.typ == hjComma || vt.typ == hjRBrace || vt.typ == hjEOF {
			continue
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		m.Pairs = append(m.Pairs, Pair{key, v})
	}
}

func (p *hjParser) parseValue() (interface{}, error) {
	tok, err := p.next()
	if err != nil {
		return nil, err
	}
	switch tok.typ {
	case hjString:
		return unquoteHJ(tok)
	case hjBool:
		return tok.raw == "true", nil
	case hjNull:
		return hclJSONNull{}, nil
	case hjNumber:
		i, err := strconv.ParseInt(tok.raw, 10, 64)
		if err != nil {
			return nil, err
		}
		return i, nil
	case hjFloat:
		f, err := strconv.ParseFloat(tok.raw, 64)
		if err != nil {
			return nil, err
		}
		return f, nil
	case hjLBrace:
		// Rewind by using a sub-parser trick: we have consumed the brace.
		// Parse the object contents manually.
		p.hasPeek = true
		t := tok
		p.peeked = &t
		p.peekErr = nil
		return p.parseObject()
	case hjLBrack:
		return p.parseListRest()
	}
	return nil, fmt.Errorf("Unknown token: %d:%d %s %s", tok.line, tok.col, tok.typ.Name(), tok.raw)
}

func (p *hjParser) parseListRest() (interface{}, error) {
	elems := []interface{}{}
	for {
		tok, err := p.peek()
		if err != nil {
			return nil, err
		}
		if tok.typ == hjEOF {
			return nil, fmt.Errorf("unexpected token while parsing list: EOF")
		}
		if tok.typ == hjRBrack {
			_, _ = p.next()
			return elems, nil
		}
		if tok.typ == hjComma {
			_, _ = p.next()
			continue
		}
		if tok.typ == hjNull {
			return nil, fmt.Errorf("unexpected token while parsing list: NULL")
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		elems = append(elems, v)
		after, err := p.peek()
		if err != nil {
			return nil, err
		}
		if after.typ == hjComma || after.typ == hjRBrack {
			continue
		}
		if after.typ == hjEOF {
			return nil, fmt.Errorf("unexpected token while parsing list: EOF")
		}
		return nil, fmt.Errorf("error parsing list, expected comma or list end, got: %s", after.typ.Name())
	}
}

func parseHCLJSON(data []byte, opts *options) (interface{}, error) {
	p := &hjParser{lex: &hjLexer{input: string(data), line: 1, col: 1}}
	obj, err := p.parseObject()
	if err != nil {
		return nil, err
	}
	return convertHCLJSONObject(obj)
}

func convertHCLJSONObject(obj *OrderedMap) (*OrderedMap, error) {
	m := &OrderedMap{}
	for _, pair := range obj.Pairs {
		if err := insertHCLJSON(m, pair.Key, pair.Value); err != nil {
			return nil, err
		}
	}
	return m, nil
}

func insertHCLJSON(m *OrderedMap, key string, v interface{}) error {
	switch t := v.(type) {
	case *OrderedMap:
		block, err := convertHCLJSONObject(t)
		if err != nil {
			return err
		}
		return appendHCLBlock(m, key, block)
	case []interface{}:
		converted, err := convertHCLJSONList(t)
		if err != nil {
			return err
		}
		return appendHCLList(m, key, converted)
	case hclJSONNull:
		// Scalar null becomes an empty string.
		for i, pr := range m.Pairs {
			if pr.Key == key {
				if _, isList := pr.Value.([]interface{}); isList {
					return fmt.Errorf("cannot set '%s' over '%s'", hclRepr(""), hclRepr(pr.Value))
				}
				m.Pairs[i].Value = ""
				return nil
			}
		}
		m.Pairs = append(m.Pairs, Pair{key, ""})
		return nil
	default:
		for i, pr := range m.Pairs {
			if pr.Key == key {
				if _, isList := pr.Value.([]interface{}); isList {
					return fmt.Errorf("cannot set '%s' over '%s'", hclRepr(v), hclRepr(pr.Value))
				}
				m.Pairs[i].Value = v
				return nil
			}
		}
		m.Pairs = append(m.Pairs, Pair{key, v})
		return nil
	}
}

func convertHCLJSONList(list []interface{}) ([]interface{}, error) {
	out := []interface{}{}
	for _, e := range list {
		switch t := e.(type) {
		case *OrderedMap:
			cm, err := convertHCLJSONObject(t)
			if err != nil {
				return nil, err
			}
			out = append(out, cm)
		case []interface{}:
			flat, err := convertHCLJSONList(t)
			if err != nil {
				return nil, err
			}
			out = append(out, flat...)
		case bool:
			// Dropped.
		case hclJSONNull:
			return nil, fmt.Errorf("unexpected token while parsing list: NULL")
		default:
			out = append(out, e)
		}
	}
	return out, nil
}

