package main

import (
	"fmt"
	"strings"
)

// Legacy (TOML 1.0 / BurntSushi v1.3) checks that newer TOML parsers accept:
// newlines and trailing commas in inline tables, and unsupported escapes.

type tomlScanner struct {
	s    string
	pos  int
	line int
}

type tomlTokKind int

const (
	ttEOF tomlTokKind = iota
	ttNewline
	ttLBrack
	ttRBrack
	ttLBrace
	ttRBrace
	ttEq
	ttComma
	ttDot
	ttString // value is decoded-ish key text for quoted keys, raw for others
	ttAtom
)

type tomlTok struct {
	kind      tomlTokKind
	text      string // atom text or string content (for keys)
	isBasic   bool
	startLine int
	endLine   int
	badEscape byte
	escapeLn  int
}

func (sc *tomlScanner) next() tomlTok {
	for sc.pos < len(sc.s) {
		c := sc.s[sc.pos]
		if c == ' ' || c == '\t' || c == '\r' {
			sc.pos++
			continue
		}
		if c == '#' {
			for sc.pos < len(sc.s) && sc.s[sc.pos] != '\n' {
				sc.pos++
			}
			continue
		}
		break
	}
	if sc.pos >= len(sc.s) {
		return tomlTok{kind: ttEOF, startLine: sc.line, endLine: sc.line}
	}
	line := sc.line
	c := sc.s[sc.pos]
	switch c {
	case '\n':
		sc.pos++
		sc.line++
		return tomlTok{kind: ttNewline, startLine: line, endLine: line}
	case '[':
		sc.pos++
		return tomlTok{kind: ttLBrack, text: "[", startLine: line}
	case ']':
		sc.pos++
		return tomlTok{kind: ttRBrack, text: "]", startLine: line}
	case '{':
		sc.pos++
		return tomlTok{kind: ttLBrace, text: "{", startLine: line}
	case '}':
		sc.pos++
		return tomlTok{kind: ttRBrace, text: "}", startLine: line}
	case '=':
		sc.pos++
		return tomlTok{kind: ttEq, text: "=", startLine: line}
	case ',':
		sc.pos++
		return tomlTok{kind: ttComma, text: ",", startLine: line}
	case '.':
		sc.pos++
		return tomlTok{kind: ttDot, text: ".", startLine: line}
	case '"', '\'':
		return sc.scanString()
	default:
		start := sc.pos
		for sc.pos < len(sc.s) {
			ch := sc.s[sc.pos]
			if ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' || strings.ContainsRune("[]{},=.#", rune(ch)) {
				break
			}
			sc.pos++
		}
		return tomlTok{kind: ttAtom, text: sc.s[start:sc.pos], startLine: line}
	}
}

func (sc *tomlScanner) scanString() tomlTok {
	startLine := sc.line
	quote := sc.s[sc.pos]
	isBasic := quote == '"'
	// Triple quoted?
	triple := false
	if sc.pos+2 < len(sc.s) && sc.s[sc.pos+1] == quote && sc.s[sc.pos+2] == quote {
		triple = true
	}
	var content strings.Builder
	var badEscape byte
	var escLine int
	if triple {
		sc.pos += 3
		for sc.pos < len(sc.s) {
			if sc.pos+2 < len(sc.s) && sc.s[sc.pos] == quote && sc.s[sc.pos+1] == quote && sc.s[sc.pos+2] == quote {
				sc.pos += 3
				break
			}
			c := sc.s[sc.pos]
			if isBasic && c == '\\' && sc.pos+1 < len(sc.s) {
				nx := sc.s[sc.pos+1]
				if badEscape == 0 && !strings.ContainsRune("btnfruU\"\\ \t\r\n", rune(nx)) {
					badEscape = nx
					escLine = sc.line
				}
				content.WriteByte(c)
				sc.pos++
				if sc.pos < len(sc.s) {
					content.WriteByte(sc.s[sc.pos])
					if sc.s[sc.pos] == '\n' {
						sc.line++
					}
					sc.pos++
				}
				continue
			}
			content.WriteByte(c)
			if c == '\n' {
				sc.line++
			}
			sc.pos++
		}
		return tomlTok{kind: ttString, text: content.String(), isBasic: isBasic, startLine: startLine, endLine: sc.line, badEscape: badEscape, escapeLn: escLine}
	}
	sc.pos++ // opening
	for sc.pos < len(sc.s) {
		c := sc.s[sc.pos]
		if c == quote {
			sc.pos++
			break
		}
		if isBasic && c == '\\' && sc.pos+1 < len(sc.s) {
			nx := sc.s[sc.pos+1]
			if badEscape == 0 && !strings.ContainsRune("btnfruU\"\\", rune(nx)) {
				badEscape = nx
				escLine = sc.line
			}
			content.WriteByte(c)
			sc.pos++
			if sc.pos < len(sc.s) {
				content.WriteByte(sc.s[sc.pos])
				sc.pos++
			}
			continue
		}
		content.WriteByte(c)
		sc.pos++
	}
	return tomlTok{kind: ttString, text: content.String(), isBasic: isBasic, startLine: startLine, endLine: sc.line, badEscape: badEscape, escapeLn: escLine}
}

type tomlLegacyChecker struct {
	sc           *tomlScanner
	peeked       *tomlTok
	hasPeek      bool
	tablePath    []string
	lastAssigned []string
}

func (c *tomlLegacyChecker) peek() tomlTok {
	if c.hasPeek {
		return *c.peeked
	}
	t := c.sc.next()
	c.peeked = &t
	c.hasPeek = true
	return t
}

func (c *tomlLegacyChecker) next() tomlTok {
	if c.hasPeek {
		t := *c.peeked
		c.hasPeek = false
		c.peeked = nil
		return t
	}
	return c.sc.next()
}

func dotted(path []string) string {
	return strings.Join(path, ".")
}

func checkTOMLLegacy(data []byte) error {
	c := &tomlLegacyChecker{sc: &tomlScanner{s: string(data), line: 1}}
	return c.parseDocument()
}

func (c *tomlLegacyChecker) parseDocument() error {
	for {
		t := c.peek()
		if t.kind == ttEOF {
			return nil
		}
		if t.kind == ttNewline {
			c.next()
			continue
		}
		if t.kind == ttLBrack {
			if err := c.parseHeader(); err != nil {
				return err
			}
			continue
		}
		// Statement assignment at document level.
		if err := c.parseAssignment(c.tablePath); err != nil {
			return err
		}
	}
}

func (c *tomlLegacyChecker) parseHeader() error {
	// Consume one or two '['
	c.next()
	if c.peek().kind == ttLBrack {
		c.next()
	}
	var path []string
	for {
		t := c.next()
		if t.kind == ttAtom || t.kind == ttString {
			path = append(path, t.text)
			continue
		}
		if t.kind == ttDot {
			continue
		}
		if t.kind == ttRBrack {
			if c.peek().kind == ttRBrack {
				c.next()
			}
			c.tablePath = path
			return nil
		}
		if t.kind == ttEOF || t.kind == ttNewline {
			c.tablePath = path
			return nil
		}
	}
}

func (c *tomlLegacyChecker) parseKeyPath() ([]string, error) {
	var path []string
	for {
		t := c.next()
		if t.kind == ttAtom || t.kind == ttString {
			path = append(path, t.text)
			if err := c.checkEscape(t, c.lastAssigned); err != nil {
				return nil, err
			}
			continue
		}
		if t.kind == ttDot {
			continue
		}
		if t.kind == ttEq {
			return path, nil
		}
		// Unexpected token in a valid document: stop.
		return path, nil
	}
}

func (c *tomlLegacyChecker) checkEscape(t tomlTok, last []string) error {
	if t.isBasic && t.badEscape != 0 {
		ln := t.startLine
		return fmt.Errorf("toml: line %d (last key %q): invalid escape in string '\\%c'", ln, dotted(last), t.badEscape)
	}
	return nil
}

func (c *tomlLegacyChecker) parseAssignment(base []string) error {
	path, err := c.parseKeyPath()
	if err != nil {
		return err
	}
	full := append(append([]string{}, base...), path...)
	c.lastAssigned = full
	return c.parseValue(full)
}

func (c *tomlLegacyChecker) parseValue(current []string) error {
	t := c.next()
	switch t.kind {
	case ttString:
		return c.checkEscape(t, current)
	case ttLBrace:
		return c.parseInline(current)
	case ttLBrack:
		return c.parseArray(current)
	default:
		return nil
	}
}

func (c *tomlLegacyChecker) parseInline(prefix []string) error {
	var lastInInline []string
	afterComma := false
	for {
		t := c.peek()
		switch t.kind {
		case ttNewline:
			return fmt.Errorf("toml: line %d (last key %q): newlines not allowed within inline tables", t.startLine, dotted(c.lastAssigned))
		case ttEOF:
			return nil
		case ttRBrace:
			c.next()
			if afterComma {
				return fmt.Errorf("toml: line %d (last key %q): trailing comma not allowed in inline tables", t.startLine, dotted(lastInInline))
			}
			return nil
		case ttComma:
			c.next()
			afterComma = true
			continue
		default:
			afterComma = false
			// Assignment inside inline table.
			before := c.lastAssigned
			if err := c.parseAssignment(prefix); err != nil {
				return err
			}
			lastInInline = c.lastAssigned
			_ = before
		}
	}
}

func (c *tomlLegacyChecker) parseArray(current []string) error {
	for {
		t := c.peek()
		switch t.kind {
		case ttEOF:
			return nil
		case ttRBrack:
			c.next()
			return nil
		case ttComma, ttNewline:
			c.next()
			continue
		default:
			if err := c.parseValue(current); err != nil {
				return err
			}
		}
	}
}
