func isSingleListWrap(v interface{}) bool {
	list, ok := v.([]interface{})
	return ok && len(list) == 1 && func() bool { _, ok := list[0].([]interface{}); return ok }()
}

func itemsFromMap(m *OrderedMap, opts *options) ([]*hclOutItem, error) {
	var out []*hclOutItem
	dropNext := false
	for _, p := range m.Pairs {
		if dropNext {
			dropNext = false
			continue
		}
		item, err := itemFromPair(p, opts)
		if err != nil {
			return nil, err
		}
		out = append(out, item...)
		if isSingleListWrap(p.Value) {
