import random, json
def scalar(v):
    if v is None: return "null"
    if isinstance(v,bool): return "true" if v else "false"
    if isinstance(v,(int,float)): return repr(v)
    # Quote strings as JSON strings (YAML double-quoted compatible mostly)
    return json.dumps(v, ensure_ascii=False)
def emit(v, indent=0):
    pad=" "*indent
    if isinstance(v,dict):
        if not v: return [pad+"{}"]
        lines=[]
        for k,val in v.items():
            ks=scalar(k)
            if isinstance(val,(dict,list)) and val:
                lines.append(f"{pad}{ks}:")
                lines.extend(emit(val, indent+2))
            else:
                if isinstance(val,dict): lines.append(f"{pad}{ks}: {{}}")
                elif isinstance(val,list): lines.append(f"{pad}{ks}: []")
                else: lines.append(f"{pad}{ks}: {scalar(val)}")
        return lines
    if isinstance(v,list):
        if not v: return [pad+"[]"]
        lines=[]
        for e in v:
            if isinstance(e,(dict,list)) and e:
                lines.append(f"{pad}-")
                lines.extend(emit(e, indent+2))
            elif isinstance(e,dict): lines.append(f"{pad}- {{}}")
            elif isinstance(e,list): lines.append(f"{pad}- []")
            else: lines.append(f"{pad}- {scalar(e)}")
        return lines
    return [pad+scalar(v)]
